import { ArrowRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import BlogLayout from '../components/BlogLayout';
import ArticleCard from '../components/ArticleCard';
import { useLocalizedPath } from '../i18n/paths';
import { posts, guides } from '../content';

export default function BlogIndex() {
  const { t, i18n } = useTranslation('edb');
  const localize = useLocalizedPath();
  const localizedPosts = posts(i18n.language);
  const localizedGuides = guides(i18n.language);
  const withImage = localizedPosts.filter((p) => p.card);
  const textOnly = localizedPosts.filter((p) => !p.card);

  return (
    <BlogLayout
      title={t('blogIndex.title')}
      description={t('blogIndex.description')}
      readTime={null}
      section="blog"
      isIndex
      wide
    >
      {/* Articles */}
      <div className="editorial-grid editorial-grid-posts grid sm:grid-cols-2 gap-6">
        {withImage.map((a) => <ArticleCard key={a.slug} article={a} />)}
      </div>

      {textOnly.length > 0 && (
        <div className="text-story-grid mt-8 grid sm:grid-cols-2 gap-4">
          {textOnly.map((a) => (
            <a
              key={a.slug}
              href={a.href}
              className="text-story group block p-5 transition-all duration-200"
            >
              <div className="flex items-center gap-2 mb-2 flex-wrap">
                <span className="article-tag text-[11px] font-semibold px-2.5 py-0.5">{a.tag}</span>
                <span className="text-[11px] text-slate-400">{a.readTime}</span>
              </div>
              <h2 className="text-base font-bold text-slate-900 dark:text-white group-hover:text-sky-600 dark:group-hover:text-sky-400 transition-colors leading-snug mb-1.5">{a.title}</h2>
              <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed">{a.description}</p>
            </a>
          ))}
        </div>
      )}

      {/* Guides */}
      <section className="related-section mt-14 pt-10 border-t">
        <div className="flex items-end justify-between gap-4 flex-wrap mb-6">
          <div className="section-intro section-intro-compact">
            <p className="text-xs font-bold text-sky-700 dark:text-sky-300 uppercase tracking-widest mb-1.5">{t('blogIndex.guidesEyebrow')}</p>
            <h2 className="text-2xl font-bold text-slate-900 dark:text-white">{t('header.guides')}</h2>
          </div>
          <a href={localize('/guides')} className="inline-flex items-center gap-1.5 text-sky-700 dark:text-sky-300 text-sm font-semibold hover:underline flex-shrink-0">
            {t('articleChrome.allGuides')} <ArrowRight className="w-4 h-4" />
          </a>
        </div>
        <div className="editorial-grid grid sm:grid-cols-2 gap-6">
          {localizedGuides.slice(0, 6).map((g) => <ArticleCard key={g.slug} article={g} />)}
        </div>
      </section>
    </BlogLayout>
  );
}
